          <input id="time-scale" type="range" min="0.25" max="3" step="0.25" value="1">
        </div>
        <div class="button-row">
          <button id="zoom-out" type="button" aria-label="Zoom out">−</button>
          <button id="zoom-in" type="button" aria-label="Zoom in">+</button>
          <button id="view-reset" type="button">Reset view</button>
        </div>
        <div class="button-row">
          <button id="play" class="primary" type="button">Play</button>
          <button id="step" type="button">Step</button>
          <button id="reset" type="button">Reset</button>
        </div>
        <button id="confirm" type="button">Confirm experiment</button>
        <p class="subtitle">Alpha and beta share gravity but start with different velocities. Each Step advances exactly 1/30 second.</p>
      </aside>
    </section>

    <footer class="timeline">
      <span class="step">Observe</span>
      <span class="step">Advance</span>
      <span class="step">Inspect</span>
      <span class="step">Confirm</span>
